/*
 * THE 200 CBS RECORDS, generated from cbs-sim/customer_accounts_200_records.xlsx.
 *
 * GENERATED, NOT HAND-WRITTEN, and not edited by hand afterwards either. If the
 * spreadsheet changes, this file is regenerated from it -- a figure corrected here and
 * not there is the kind of difference nobody finds until a balance is wrong on screen.
 *
 * THE RWF COLUMNS ARE ROUNDED TO WHOLE FRANCS ON THE WAY IN, and that is the one place
 * this file does not reproduce its source exactly. RWF has no minor unit; the spreadsheet
 * carried two decimals on 648 of its 660 non-zero RWF balances, which is how it was
 * generated rather than anything the bank does. The portal parses money strictly against
 * each currency's own scale, so those centimes were refused at the counter -- correctly.
 * Rounding here keeps that rule intact; the alternative was to let RWF carry decimals in
 * the portal, which is the rule that stops a rounding decision nobody made from reaching
 * somebody's balance.
 *
 * USD, EUR and GBP keep their two decimals, because those currencies have them.
 *
 * Run cbs-sim/01-schema.sql first; this file assumes the table exists and is empty.
 */

USE ZigamaCbs;
GO

SET NOCOUNT ON;
GO


GO

GO

GO

GO

/* ---------------------------------------------------------------- verification
 * Every figure below was computed from the spreadsheet before this file was written.
 */
DECLARE @fail INT = 0;

IF (SELECT COUNT(*) FROM customer_accounts) <> 200
    BEGIN PRINT 'FAIL: expected 200 rows'; SET @fail = 1; END

IF (SELECT COUNT(*) FROM customer_accounts WHERE Categ = 'M') <> 172
    BEGIN PRINT 'FAIL: expected 172 individuals'; SET @fail = 1; END

IF (SELECT COUNT(*) FROM customer_accounts WHERE AStatus = 'Domant') <> 22
    BEGIN PRINT 'FAIL: expected 22 dormant'; SET @fail = 1; END

IF (SELECT COUNT(DISTINCT TelephoneNumber) FROM customer_accounts) <> 200
    BEGIN PRINT 'FAIL: telephone numbers are not unique -- OTP cannot identify a customer'; SET @fail = 1; END

/* The rule the schema also enforces, checked from this side too. */
IF EXISTS (SELECT 1 FROM customer_accounts
           WHERE BalanceCurrentAc <> FLOOR(BalanceCurrentAc)
              OR BalanceCompAc <> FLOOR(BalanceCompAc)
              OR BalanceVolAc <> FLOOR(BalanceVolAc)
              OR BalanceFixedac <> FLOOR(BalanceFixedac)
              OR BalanceEducationSavings <> FLOOR(BalanceEducationSavings))
    BEGIN PRINT 'FAIL: an RWF balance has a fractional part'; SET @fail = 1; END

IF (SELECT COUNT(*) FROM customer_accounts
    WHERE BalanceCurrentAc + BalanceCompAc + BalanceVolAc + BalanceFixedac
        + BalanceEducationSavings + BalanceCurrentacUSD + BalancecompSavingsUSD
        + BalancevoluSavingsUSD + BalanceFixedacUSD + BalanceCurrentacEuro
        + BalancecompSavingsEuro + BalancevoluSavingsEuro + BalanceFixedacEuro
        + BalanceCurrentacPound + BalancecompSavingsPound + BalancevoluSavingsPound
        + BalanceFixedacPound = 0) <> 1
    BEGIN PRINT 'FAIL: expected exactly one customer with every balance zero'; SET @fail = 1; END

IF @fail = 0 PRINT 'All checks passed: 200 rows loaded and verified.';
GO
